-- GROUP G1: art.field lists every field an artist works in, main field first; a per-main-field question needs one field per artist (the main one), a who-works-in-sculpture question needs the whole list
-- TYPE: list-vs-one
-- COLUMN: art.field
-- NOTE: FORM G1a is what an extraction asked for "the artist's main field" stores: the first listed field ('Public Sculpture', 1 row, stored as Sculpture). 599 of 1003 rows are lists.
-- NOTE: Spot-check of 12 list rows against source_data/Art/wikiart: the first item agrees with the first field the lead sentence names ("a Dutch painter, sculptor, and poet" -> Painting||Sculpture||Poetry).
-- NOTE: G1a is restricted to three fields in the description's vocabulary, so out-of-vocabulary first items ('Art', 'Poetry', 'Visual art') play no role. Painting is left out: at 699 of 1003 artists it sets the scorer's value range alone, and the other fields' errors then fall inside the 20% tolerance (raw scored 0.75 at 20% with it).
-- FORM G1a: UPDATE art SET field = CASE WHEN trim(CASE WHEN instr(field, '||') > 0 THEN substr(field, 1, instr(field, '||') - 1) ELSE field END) = 'Public Sculpture' THEN 'Sculpture' ELSE trim(CASE WHEN instr(field, '||') > 0 THEN substr(field, 1, instr(field, '||') - 1) ELSE field END) END;
-- G1a: For artists whose main field is sculpture, photography or illustration: how many artists per field, how many taught, and how many won at least one award?
SELECT field, COUNT(*) AS artists, SUM(teaching) AS teachers, SUM(CASE WHEN awards >= 1 THEN 1 ELSE 0 END) AS award_winners FROM art WHERE field IN ('Sculpture', 'Photography', 'Illustration') GROUP BY field;
-- KEY G1a:
SELECT field, COUNT(*) AS artists, SUM(teaching) AS teachers, SUM(CASE WHEN awards >= 1 THEN 1 ELSE 0 END) AS award_winners FROM (SELECT CASE WHEN trim(CASE WHEN instr(field, '||') > 0 THEN substr(field, 1, instr(field, '||') - 1) ELSE field END) = 'Public Sculpture' THEN 'Sculpture' ELSE trim(CASE WHEN instr(field, '||') > 0 THEN substr(field, 1, instr(field, '||') - 1) ELSE field END) END AS field, teaching, awards FROM art) WHERE field IN ('Sculpture', 'Photography', 'Illustration') GROUP BY field;

-- G1b: Per birth continent with at least five such artists, how many artists work in sculpture (alone or alongside other fields), and how many of them taught?
SELECT birth_continent, COUNT(*) AS sculptors, SUM(teaching) AS teachers FROM art WHERE field LIKE '%Sculpture%' AND birth_continent <> '' GROUP BY birth_continent HAVING COUNT(*) >= 5;
-- KEY G1b:
SELECT birth_continent, COUNT(*) AS sculptors, SUM(teaching) AS teachers FROM art WHERE field LIKE '%Sculpture%' AND birth_continent <> '' GROUP BY birth_continent HAVING COUNT(*) >= 5;

-- GROUP G2: art.genre lists every genre an artist works in, main genre first; a per-main-genre question needs one genre per artist in the description's vocabulary, a who-paints-both-portraits-and-landscapes question needs the whole list
-- TYPE: list-vs-one
-- COLUMN: art.genre
-- NOTE: FORM G2a is what an extraction asked for "the artist's main genre", choosing from the description's vocabulary, stores: the first listed genre, with variants folded into the vocabulary term (any portrait genre such as Portraiture or Self-Portrait -> Portrait; any landscape genre such as Landscapes or Urban landscape -> Landscape; Abstract..., Abstraction, Geometric Abstraction -> Abstract). 'Semi-abstract' and 'Figurative abstraction' stay as stated. 384 rows are lists.
-- FORM G2a: UPDATE art SET genre = CASE WHEN lower(trim(CASE WHEN instr(genre, '||') > 0 THEN substr(genre, 1, instr(genre, '||') - 1) ELSE genre END)) LIKE '%portrait%' THEN 'Portrait' WHEN lower(trim(CASE WHEN instr(genre, '||') > 0 THEN substr(genre, 1, instr(genre, '||') - 1) ELSE genre END)) LIKE '%landscape%' THEN 'Landscape' WHEN lower(trim(CASE WHEN instr(genre, '||') > 0 THEN substr(genre, 1, instr(genre, '||') - 1) ELSE genre END)) LIKE 'abstract%' OR lower(trim(CASE WHEN instr(genre, '||') > 0 THEN substr(genre, 1, instr(genre, '||') - 1) ELSE genre END)) = 'geometric abstraction' THEN 'Abstract' ELSE trim(CASE WHEN instr(genre, '||') > 0 THEN substr(genre, 1, instr(genre, '||') - 1) ELSE genre END) END;
-- G2a: For artists whose main genre is portrait, landscape or abstract: how many artists per genre, how many taught, and what share won at least one award?
SELECT genre, COUNT(*) AS artists, SUM(teaching) AS teachers, AVG(CASE WHEN awards >= 1 THEN 1.0 ELSE 0.0 END) AS share_award_winners FROM art WHERE genre IN ('Portrait', 'Landscape', 'Abstract') GROUP BY genre;
-- KEY G2a:
SELECT genre, COUNT(*) AS artists, SUM(teaching) AS teachers, AVG(CASE WHEN awards >= 1 THEN 1.0 ELSE 0.0 END) AS share_award_winners FROM (SELECT CASE WHEN lower(trim(CASE WHEN instr(genre, '||') > 0 THEN substr(genre, 1, instr(genre, '||') - 1) ELSE genre END)) LIKE '%portrait%' THEN 'Portrait' WHEN lower(trim(CASE WHEN instr(genre, '||') > 0 THEN substr(genre, 1, instr(genre, '||') - 1) ELSE genre END)) LIKE '%landscape%' THEN 'Landscape' WHEN lower(trim(CASE WHEN instr(genre, '||') > 0 THEN substr(genre, 1, instr(genre, '||') - 1) ELSE genre END)) LIKE 'abstract%' OR lower(trim(CASE WHEN instr(genre, '||') > 0 THEN substr(genre, 1, instr(genre, '||') - 1) ELSE genre END)) = 'geometric abstraction' THEN 'Abstract' ELSE trim(CASE WHEN instr(genre, '||') > 0 THEN substr(genre, 1, instr(genre, '||') - 1) ELSE genre END) END AS genre, teaching, awards FROM art) WHERE genre IN ('Portrait', 'Landscape', 'Abstract') GROUP BY genre;

-- G2b: Per birth continent with at least five such artists, how many artists work in both portraits and landscapes, and how many of them taught?
SELECT birth_continent, COUNT(*) AS artists, SUM(teaching) AS teachers FROM art WHERE genre LIKE '%Portrait%' AND genre LIKE '%Landscape%' AND birth_continent <> '' GROUP BY birth_continent HAVING COUNT(*) >= 5;
-- KEY G2b:
SELECT birth_continent, COUNT(*) AS artists, SUM(teaching) AS teachers FROM art WHERE genre LIKE '%Portrait%' AND genre LIKE '%Landscape%' AND birth_continent <> '' GROUP BY birth_continent HAVING COUNT(*) >= 5;

-- GROUP G3: art.art_movement lists every movement an artist took part in, main movement first; a per-main-movement question needs one movement per artist, a who-took-part-in question needs the whole list
-- TYPE: list-vs-one
-- COLUMN: art.art_movement
-- NOTE: FORM G3a is what an extraction asked for "the artist's main movement" stores: the first listed movement, with the movement name normalized (case variants such as 'Abstract expressionism' and 'Pop art'; named varieties such as 'Persian Surrealism' count as Surrealism, the same membership test G3b's LIKE applies).
-- NOTE: Minimalism is left out: '%Minimalism%' would count Postminimalism and miss 'Minimal Art'. 'Pop' (1 row) and 'Political Pop' (1 row) are not counted as Pop Art in either question.
-- FORM G3a: UPDATE art SET art_movement = CASE WHEN lower(trim(CASE WHEN instr(art_movement, '||') > 0 THEN substr(art_movement, 1, instr(art_movement, '||') - 1) ELSE art_movement END)) LIKE '%surrealism%' THEN 'Surrealism' WHEN lower(trim(CASE WHEN instr(art_movement, '||') > 0 THEN substr(art_movement, 1, instr(art_movement, '||') - 1) ELSE art_movement END)) LIKE '%abstract expressionism%' THEN 'Abstract Expressionism' WHEN lower(trim(CASE WHEN instr(art_movement, '||') > 0 THEN substr(art_movement, 1, instr(art_movement, '||') - 1) ELSE art_movement END)) LIKE '%pop art%' THEN 'Pop Art' ELSE trim(CASE WHEN instr(art_movement, '||') > 0 THEN substr(art_movement, 1, instr(art_movement, '||') - 1) ELSE art_movement END) END;
-- G3a: For artists whose main movement is Surrealism, Abstract Expressionism or Pop Art: how many artists per movement, how many taught, and how many won at least one award?
SELECT art_movement, COUNT(*) AS artists, SUM(teaching) AS teachers, SUM(CASE WHEN awards >= 1 THEN 1 ELSE 0 END) AS award_winners FROM art WHERE art_movement IN ('Surrealism', 'Abstract Expressionism', 'Pop Art') GROUP BY art_movement;
-- KEY G3a:
SELECT art_movement, COUNT(*) AS artists, SUM(teaching) AS teachers, SUM(CASE WHEN awards >= 1 THEN 1 ELSE 0 END) AS award_winners FROM (SELECT CASE WHEN lower(trim(CASE WHEN instr(art_movement, '||') > 0 THEN substr(art_movement, 1, instr(art_movement, '||') - 1) ELSE art_movement END)) LIKE '%surrealism%' THEN 'Surrealism' WHEN lower(trim(CASE WHEN instr(art_movement, '||') > 0 THEN substr(art_movement, 1, instr(art_movement, '||') - 1) ELSE art_movement END)) LIKE '%abstract expressionism%' THEN 'Abstract Expressionism' WHEN lower(trim(CASE WHEN instr(art_movement, '||') > 0 THEN substr(art_movement, 1, instr(art_movement, '||') - 1) ELSE art_movement END)) LIKE '%pop art%' THEN 'Pop Art' ELSE trim(CASE WHEN instr(art_movement, '||') > 0 THEN substr(art_movement, 1, instr(art_movement, '||') - 1) ELSE art_movement END) END AS art_movement, teaching, awards FROM art) WHERE art_movement IN ('Surrealism', 'Abstract Expressionism', 'Pop Art') GROUP BY art_movement;

-- G3b: For artists born in Europe and in North America, how many took part in Surrealism, in Pop Art and in Abstract Expressionism at any point in their career?
SELECT birth_continent, SUM(CASE WHEN art_movement LIKE '%Surrealism%' THEN 1 ELSE 0 END) AS surrealism, SUM(CASE WHEN art_movement LIKE '%Pop Art%' THEN 1 ELSE 0 END) AS pop_art, SUM(CASE WHEN art_movement LIKE '%Abstract Expressionism%' THEN 1 ELSE 0 END) AS abstract_expressionism FROM art WHERE birth_continent IN ('Europe', 'North America') GROUP BY birth_continent;
-- KEY G3b:
SELECT birth_continent, SUM(CASE WHEN art_movement LIKE '%Surrealism%' THEN 1 ELSE 0 END) AS surrealism, SUM(CASE WHEN art_movement LIKE '%Pop Art%' THEN 1 ELSE 0 END) AS pop_art, SUM(CASE WHEN art_movement LIKE '%Abstract Expressionism%' THEN 1 ELSE 0 END) AS abstract_expressionism FROM art WHERE birth_continent IN ('Europe', 'North America') GROUP BY birth_continent;

-- GROUP G13: art.birth_date holds the full date of birth as stated ('1885/3/2'); a per-birth-year question that filters and groups on year numbers needs the year alone as a number, a question about birth dates of 1 January (a common stand-in for an unknown day) needs the full date
-- TYPE: number-vs-text
-- COLUMN: art.birth_date
-- NOTE: FORM G13a stores the four-digit year of every well-formed date (976 rows); the two malformed values ('186110/17' and a non-date string) stay as stated.
-- NOTE: The column has TEXT affinity, so FORM G13a stores the year as the text '1881' while the key returns the integer 1881; the scorer compares the two numerically. On the stated values, birth_date BETWEEN 1881 AND 1890 compares text and returns one group per full date from 1881 to 1889, so the stated form fails G13a without an error.
-- FORM G13a: UPDATE art SET birth_date = CAST(substr(birth_date, 1, 4) AS INTEGER) WHERE birth_date GLOB '[0-9][0-9][0-9][0-9]/*';
-- G13a: For each birth year from 1881 to 1890, how many artists were born that year, how many taught, and how many won at least one award?
SELECT birth_date, COUNT(*) AS artists, SUM(teaching) AS teachers, SUM(CASE WHEN awards >= 1 THEN 1 ELSE 0 END) AS award_winners FROM art WHERE birth_date BETWEEN 1881 AND 1890 GROUP BY birth_date;
-- KEY G13a:
SELECT birth_date, COUNT(*) AS artists, SUM(teaching) AS teachers, SUM(CASE WHEN awards >= 1 THEN 1 ELSE 0 END) AS award_winners FROM (SELECT CAST(substr(birth_date, 1, 4) AS INTEGER) AS birth_date, teaching, awards FROM art WHERE birth_date GLOB '[0-9][0-9][0-9][0-9]/*') WHERE birth_date BETWEEN 1881 AND 1890 GROUP BY birth_date;

-- G13b: Per birth continent, how many artists have a birth date of 1 January (often a stand-in when only the year is known), and how many of them taught?
SELECT birth_continent, COUNT(*) AS artists, SUM(teaching) AS teachers FROM art WHERE birth_date LIKE '%/1/1' AND birth_continent <> '' GROUP BY birth_continent;
-- KEY G13b:
SELECT birth_continent, COUNT(*) AS artists, SUM(teaching) AS teachers FROM art WHERE birth_date LIKE '%/1/1' AND birth_continent <> '' GROUP BY birth_continent;

-- GROUP G14: art.color describes the featured image's dominant colors as stated ('Blue', 'Earth Tones', 'Red', 'Warm Tones (Reds, Oranges)'); a warm-versus-cool palette question needs each palette stored as its temperature (Warm, Cool), a question about specific colors needs the stated color
-- TYPE: fine-vs-coarse
-- COLUMN: art.color
-- NOTE: FORM G14a applies one mechanical rule to the words of each value (plurals folded: Reds -> red). Warm hues: red, orange, yellow, pink, brown, gold/golden, bronze, rust, earth/earthy (earth tones), and the word warm. Cool hues: blue, green, purple, turquoise, and the word cool. Every other word (black, white, gray/grey, beige, cream, sepia, dark, light, muted, pastel, tones, ...) is ignored. A value becomes 'Warm' when it names at least one warm hue and no cool hue, 'Cool' when it names at least one cool hue and no warm hue. It stays as stated when it names hues of both kinds ('Blue And Orange', 'Earth Tones (Browns, Greens)'), names no hue ('Black And White', 'Sepia', 'Monochrome'), or describes a mixed or accented palette (multicolor(ed), multi-colored, various, mixed, rainbow, vibrant, accent(s), highlights, splashes, hints, pops, drips: e.g. 'Dark Tones With Red Accents', 'Dark With Hints Of Warm Tones').
-- NOTE: Examples: 'Red And Black', 'Pink', 'Gold And Cream', 'Earth Tones, White' -> Warm; 'Blue And Gray', 'Purple', 'Predominantly White And Purple' -> Cool. 75 distinct values become Warm and 32 Cool; 598 rows change (392 Warm, 206 Cool).
-- FORM G14a: UPDATE art SET color = CASE WHEN color IN ('Beige/Brown', 'Black, Brown, Red', 'Black, Gray, Red', 'Black, Red', 'Black, White, Red', 'Black, Yellow, White', 'Bright Yellow', 'Bronze', 'Brown', 'Brown And Black', 'Dark And Earthy Tones', 'Dark Brown', 'Dark Earth Tones', 'Dark Red', 'Dark Tones With Earth Colors', 'Dark Tones With Earthy Hues', 'Dark Tones With Red And Pale Skin', 'Dark, With Prominent Use Of Red And White', 'Earth Tones', 'Earth Tones (Brown, Beige, And Muted Red)', 'Earth Tones And Reds', 'Earth Tones, Muted Colors', 'Earth Tones, Predominantly Brown And Orange', 'Earth Tones, White', 'Earth Tones, With Reds And Whites', 'Earth Tones, Yellow, Brown', 'Earthy Tones', 'Gold', 'Gold And Cream', 'Golden', 'Gray, Red, Yellow-Orange', 'Light Earth Tones', 'Muted Browns And Grays', 'Muted Earth Tones', 'Muted Earthy Tones', 'Muted Tones, Earthy Colors', 'Neutral Tones (Beige, Brown)', 'Orange', 'Orange And Beige', 'Orange And Yellow', 'Orange, Gray, Yellow', 'Pink', 'Predominantly Earthy Tones', 'Predominantly Pink And White', 'Predominantly Warm Colors (Pinks, Browns)', 'Red', 'Red And Black', 'Red And White', 'Red, Black', 'Red, Black, Gray', 'Red, Brown', 'Red, Orange, Grey', 'Red, Yellow, White', 'Red/White', 'Rust', 'Soft Beige And Earth Tones', 'Warm Autumn Tones', 'Warm Colors', 'Warm Earth Tones', 'Warm Hues', 'Warm Hues (Yellow, Orange)', 'Warm Tones', 'Warm Tones (Browns And Reds)', 'Warm Tones (Browns, Reds, And Whites)', 'Warm Tones (Golden, Brown)', 'Warm Tones (Orange And Gold)', 'Warm Tones (Orange, Yellow)', 'Warm Tones (Reds, Oranges)', 'Warm Tones (Reds, Oranges, Yellows)', 'Warm Tones (Reds, Yellows)', 'Warm Tones (Yellows, Browns)', 'Warm Tones With Prominent Use Of Yellows, Browns, And Reds', 'Yellow', 'Yellow, Black, Red', 'Yellow, Red, Gray') THEN 'Warm' WHEN color IN ('Beige And Blue', 'Black, Blue, White', 'Blue', 'Blue And Beige', 'Blue And Black', 'Blue And Gray', 'Blue And Green', 'Blue, Black', 'Blue-Green', 'Blues And Greens', 'Dark Blue', 'Dark Blue And Green', 'Dark Blue Tones', 'Dark Blue, Black', 'Dark Blues And Blacks', 'Dark Blues And Grays', 'Dark Green', 'Dark Purple', 'Dark Tones With Muted Blues And Blacks', 'Green', 'Green, Purple', 'Grey, Blue, Green', 'Light Blue', 'Light Green', 'Muted Blue And Gray', 'Pastel Blues And Greens', 'Predominantly Blue And Green', 'Predominantly Light Blue And White', 'Predominantly White And Purple', 'Purple', 'Purple, Black, White', 'White, Blue, Green, Black') THEN 'Cool' ELSE color END;
-- G14a: Comparing featured images with a warm palette and with a cool palette: how many images of each, how many of their artists taught, and how many won at least one award?
SELECT color, COUNT(*) AS images, SUM(teaching) AS teachers, SUM(CASE WHEN awards >= 1 THEN 1 ELSE 0 END) AS award_winners FROM art WHERE color IN ('Warm', 'Cool') GROUP BY color;
-- KEY G14a:
SELECT color, COUNT(*) AS images, SUM(teaching) AS teachers, SUM(CASE WHEN awards >= 1 THEN 1 ELSE 0 END) AS award_winners FROM (SELECT CASE WHEN color IN ('Beige/Brown', 'Black, Brown, Red', 'Black, Gray, Red', 'Black, Red', 'Black, White, Red', 'Black, Yellow, White', 'Bright Yellow', 'Bronze', 'Brown', 'Brown And Black', 'Dark And Earthy Tones', 'Dark Brown', 'Dark Earth Tones', 'Dark Red', 'Dark Tones With Earth Colors', 'Dark Tones With Earthy Hues', 'Dark Tones With Red And Pale Skin', 'Dark, With Prominent Use Of Red And White', 'Earth Tones', 'Earth Tones (Brown, Beige, And Muted Red)', 'Earth Tones And Reds', 'Earth Tones, Muted Colors', 'Earth Tones, Predominantly Brown And Orange', 'Earth Tones, White', 'Earth Tones, With Reds And Whites', 'Earth Tones, Yellow, Brown', 'Earthy Tones', 'Gold', 'Gold And Cream', 'Golden', 'Gray, Red, Yellow-Orange', 'Light Earth Tones', 'Muted Browns And Grays', 'Muted Earth Tones', 'Muted Earthy Tones', 'Muted Tones, Earthy Colors', 'Neutral Tones (Beige, Brown)', 'Orange', 'Orange And Beige', 'Orange And Yellow', 'Orange, Gray, Yellow', 'Pink', 'Predominantly Earthy Tones', 'Predominantly Pink And White', 'Predominantly Warm Colors (Pinks, Browns)', 'Red', 'Red And Black', 'Red And White', 'Red, Black', 'Red, Black, Gray', 'Red, Brown', 'Red, Orange, Grey', 'Red, Yellow, White', 'Red/White', 'Rust', 'Soft Beige And Earth Tones', 'Warm Autumn Tones', 'Warm Colors', 'Warm Earth Tones', 'Warm Hues', 'Warm Hues (Yellow, Orange)', 'Warm Tones', 'Warm Tones (Browns And Reds)', 'Warm Tones (Browns, Reds, And Whites)', 'Warm Tones (Golden, Brown)', 'Warm Tones (Orange And Gold)', 'Warm Tones (Orange, Yellow)', 'Warm Tones (Reds, Oranges)', 'Warm Tones (Reds, Oranges, Yellows)', 'Warm Tones (Reds, Yellows)', 'Warm Tones (Yellows, Browns)', 'Warm Tones With Prominent Use Of Yellows, Browns, And Reds', 'Yellow', 'Yellow, Black, Red', 'Yellow, Red, Gray') THEN 'Warm' WHEN color IN ('Beige And Blue', 'Black, Blue, White', 'Blue', 'Blue And Beige', 'Blue And Black', 'Blue And Gray', 'Blue And Green', 'Blue, Black', 'Blue-Green', 'Blues And Greens', 'Dark Blue', 'Dark Blue And Green', 'Dark Blue Tones', 'Dark Blue, Black', 'Dark Blues And Blacks', 'Dark Blues And Grays', 'Dark Green', 'Dark Purple', 'Dark Tones With Muted Blues And Blacks', 'Green', 'Green, Purple', 'Grey, Blue, Green', 'Light Blue', 'Light Green', 'Muted Blue And Gray', 'Pastel Blues And Greens', 'Predominantly Blue And Green', 'Predominantly Light Blue And White', 'Predominantly White And Purple', 'Purple', 'Purple, Black, White', 'White, Blue, Green, Black') THEN 'Cool' ELSE color END AS color, teaching, awards FROM art) WHERE color IN ('Warm', 'Cool') GROUP BY color;

-- G14b: How many featured images are dominated by blue, by green, by red and by yellow, how many of their artists taught, and how many won at least one award?
SELECT color, COUNT(*) AS images, SUM(teaching) AS teachers, SUM(CASE WHEN awards >= 1 THEN 1 ELSE 0 END) AS award_winners FROM art WHERE color IN ('Blue', 'Green', 'Red', 'Yellow') GROUP BY color;
-- KEY G14b:
SELECT color, COUNT(*) AS images, SUM(teaching) AS teachers, SUM(CASE WHEN awards >= 1 THEN 1 ELSE 0 END) AS award_winners FROM art WHERE color IN ('Blue', 'Green', 'Red', 'Yellow') GROUP BY color;
